begin;
set local statement_timeout='30s';
create function pg_temp.social_assert(ok boolean,why text) returns void language plpgsql as $$
begin if ok is distinct from true then raise exception 'FAIL: %',why; end if; end $$;
create temporary table social_ids(label text primary key,id uuid);
create temporary table social_revisions(label text primary key,value bigint);
grant select,insert on social_ids,social_revisions to authenticated;
insert into social_ids values('author_auth',gen_random_uuid()),('peer_auth',gen_random_uuid()),('outsider_auth',gen_random_uuid());
update private.app_admission_settings set enabled=false where singleton;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
  select id,'updates-fixture-'||id||'@example.test',clock_timestamp(),'{"display_name":"Live updates fixture"}' from social_ids;
insert into social_ids select replace(i.label,'_auth','_profile'),l.profile_id from social_ids i join private.profile_auth_links l on l.auth_user_id=i.id;
insert into private.profile_usernames(profile_id,username) select id,'Signal'||replace(id::text,'-','')::varchar(20) from social_ids where label like '%_profile';
select pg_temp.social_assert(not has_table_privilege('anon','public.conversation_updates','SELECT'),'anonymous signals denied');
select pg_temp.social_assert(not has_table_privilege('authenticated','public.account_updates','UPDATE'),'client signal writes denied');
select pg_temp.social_assert((select count(*)=2 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename in('conversation_updates','account_updates')),'signal tables published');
select pg_temp.social_assert((select count(*)=3 from information_schema.columns where table_schema='public' and table_name='conversation_updates'),'no content fields in conversation signal');
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('request.jwt.claim.sub',(select id::text from social_ids where label='author_auth'),true);
set local role authenticated;
insert into social_ids values('group',public.create_group('Live signal SQL fixture'));
reset role;
insert into public.group_memberships(group_id,user_id,role,state) values((select id from social_ids where label='group'),(select id from social_ids where label='peer_profile'),'member','active');
insert into public.membership_periods(group_id,user_id) values((select id from social_ids where label='group'),(select id from social_ids where label='peer_profile'));
insert into social_revisions select 'table_before',revision from public.conversation_updates where group_id=(select id from social_ids where label='group');
insert into social_revisions select 'peer_before',revision from public.account_updates where profile_id=(select id from social_ids where label='peer_profile');
set local role authenticated;
insert into social_ids values('request',public.post_table_request((select id from social_ids where label='group'),gen_random_uuid(),'Signal test question','Hello @'||(select username from public.table_mention_members((select id from social_ids where label='group')) where profile_id=(select id from social_ids where label='peer_profile'))));
select pg_temp.social_assert((select revision>(select value from social_revisions where label='table_before') from public.conversation_updates where group_id=(select id from social_ids where label='group')),'message signals Table change');
reset role;
select pg_temp.social_assert((select revision>(select value from social_revisions where label='peer_before') from public.account_updates where profile_id=(select id from social_ids where label='peer_profile')),'mention signals recipient');
insert into social_ids select 'thread',id from public.threads where root_entry_id=(select id from social_ids where label='request');
insert into social_revisions select 'table_reply_before',revision from public.conversation_updates where group_id=(select id from social_ids where label='group');
set local role authenticated;
select public.reply_to_thread((select id from social_ids where label='thread'),gen_random_uuid(),'Signal reply');
select pg_temp.social_assert((select revision>(select value from social_revisions where label='table_reply_before') from public.conversation_updates where group_id=(select id from social_ids where label='group')),'reply signals Table change');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from social_ids where label='outsider_auth'),true);
set local role authenticated;
select pg_temp.social_assert((select count(*)=0 from public.conversation_updates where group_id=(select id from social_ids where label='group')),'outsider receives no Table signal');
select pg_temp.social_assert((select count(*)=1 from public.account_updates where profile_id in(select id from social_ids)),'own account signals only');
reset role;
select set_config('request.jwt.claim.sub',(select id::text from social_ids where label='peer_auth'),true);
set local role authenticated;
select pg_temp.social_assert((select count(*)=1 from public.conversation_updates where group_id=(select id from social_ids where label='group')),'active peer may read signal');
select public.read_mention_notification((select id from public.my_mention_notifications() limit 1));
reset role;
insert into social_revisions select 'peer_leave_before',revision from public.account_updates where profile_id=(select id from social_ids where label='peer_profile');
update public.membership_periods set ended_at=greatest(clock_timestamp(),joined_at+interval '1 microsecond'),end_reason='left'
  where group_id=(select id from social_ids where label='group') and user_id=(select id from social_ids where label='peer_profile') and ended_at is null;
update public.group_memberships set state='left' where group_id=(select id from social_ids where label='group') and user_id=(select id from social_ids where label='peer_profile');
select pg_temp.social_assert((select revision>(select value from social_revisions where label='peer_leave_before') from public.account_updates where profile_id=(select id from social_ids where label='peer_profile')),'departure signals own refresh');
set local role authenticated;
select pg_temp.social_assert((select count(*)=0 from public.conversation_updates where group_id=(select id from social_ids where label='group')),'former member denied signals');
reset role;
set constraints all immediate;
select 'PASS updates: content-free publication, active-member RLS, own account signals, message/reply/mention/read/departure changes and former-member denial' as result;
rollback;
